entries[167542] = { ["name"] = "Glänzende azurblaue Schuppen", ["text"] = "Questgegenstand\n\"Das Licht bricht sich an den Schuppen in schillernder und blitzender Weise, verursacht durch die nun gut sichtbaren Spuren, die von zahllosen Kämpfen hinterlassen wurden.\"" }
