entries[167546] = { ["name"] = "Gesegnete Opfergabe", ["text"] = "Questgegenstand\n\"Die Kräuter im Inneren leuchten schwach und bewegen sich von selbst.\"" }
entries[167547] = { ["name"] = "Tiefseetauchhelm", ["text"] = "Questgegenstand\nEinzigartig\nKopf\nAnlegen: Ermöglicht es dem Träger, unter Wasser zu atmen. Ihr müsst Euch in Sichtweite der Boje befinden, die in der Dolchbucht schwimmt.\nVerkaufspreis:" }
