entries[167731] = { ["name"] = "Rüstungsschutz für kampfbewährte Erbstücke", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Wertet Erbstückrüstungen, Schmuckstücke oder Gegenstände für die Schildhand auf, sodass sie bis Stufe 50 aufsteigen können.\n\nFunktioniert nur bei Erbstücken, die auf Stufe 45 aufsteigen können." }
entries[167732] = { ["name"] = "Waffenscheide für kampfbewährte Erbstücke", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Wertet Erbstückwaffen auf, sodass sie bis Stufe 50 aufsteigen können.\n\nFunktioniert nur bei Erbstücken, die auf Stufe 45 aufsteigen können." }
entries[167733] = { ["name"] = "Technik: Glyphe der Dalaranbrillanz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man die Glyphe 'Dalaranbrillanz' schreibt.\nBenötigt Inschriftenkunde von Nordend (1)\nVerkaufspreis:\nGlyphe der Dalaranbrillanz\nKlassen: Magier\nBenutzen: Modifiziert Eure 'Arkane Intelligenz', damit sie visuell der 'Dalaranbrillanz' der Kirin Tor ähnelt.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Meerestinte (3)" }
entries[167737] = { ["name"] = "Dreifach gefalteter Brief", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Die Seite ist auf eine besondere Weise gefaltet, als ob damit etwas Bestimmtes ausgedrückt werden sollte.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[167738] = { ["name"] = "Vergoldetes Seetuch", ["text"] = "Handwerksmaterial\n\"Wird von getöteten Kreaturen eingesammelt. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[167739] = { ["name"] = "Tiefenrochenrogen", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 10000 * 20 / 5) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[167740] = { ["name"] = "Spaltbeil", ["text"] = "Wird beim Anlegen gebunden\nWaffenhand\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\n\"Diese Klinge ist stumpf, entweder durch Verwendung im Kampf oder aber um zu verhindern, dass neue Rekruten sich damit ernsthaft verletzen.\"\nVerkaufspreis:" }
entries[167741] = { ["name"] = "Rekrutenschild", ["text"] = "Wird beim Anlegen gebunden\nSchildhand Schild\n13 Rüstung\n\"Dieser Holzschild hat schon bessere Tage gesehen. Wenigstens zieht man sich daran keine Splitter.\"\nVerkaufspreis:" }
entries[167742] = { ["name"] = "Silas' Karaffe der Maskierung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde (Realzeit)\nHebt verschiedene Kessel in Kul Tiras und Zandalar hervor und gestattet es dem Spielercharakter, mit ihnen zu interagieren.\nBenutzen: Verkleidet den Anwender als eins der vielen Geschöpfe dieser Welt. (1 Min Abklingzeit)\nBenötigt Alchemie von Kul Tiras\n(1)" }
entries[167743] = { ["name"] = "Silas' Trank des Wohlstands", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde (Realzeit)\nHebt verschiedene Kessel in Kul Tiras und Zandalar hervor und gestattet es dem Spielercharakter, mit ihnen zu interagieren.\nBenutzen: Erhöht die Chance, zusätzliche Alchemiegegenstände von Zandalar herzustellen. (20 Min Abklingzeit)\nBenötigt Alchemie von Kul Tiras\n(1)" }
entries[167744] = { ["name"] = "Ausrüstungstruhe des Aspiranten", ["text"] = "Wird beim Aufheben gebunden\n\"Gewährt ein Ausrüstungsteil für Eure Beutespezialisierung.\"" }
