entries[167747] = { ["name"] = "Spieluhr des Suchers", ["text"] = "Prototyp\nWird beim Aufheben gebunden\nBenutzen: Läutert sämtliche Wahnsinnsleiden und betäubt Gegner innerhalb von 5 Metern. Kann im Kampf benutzt werden.\n\"Das Lied der Sucher sorgt selbst im Kampf für klaren Verstand.\"" }
entries[167748] = { ["name"] = "Stein der Elemente", ["text"] = "Questgegenstand\nBenutzen: Befriedet einen instabilen Tidenwoger.\n\nDamit dies funktioniert, muss der Elementar geschwächt sein. (5 Sek. Abklingzeit)" }
entries[167751] = { ["name"] = "Laserpointer für Mechanokatzen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man eine Mechanokatze X-995 beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die X-995 ist das Nonplusultra in Sachen anpassbarer Robokatzengefährtschaft.\"\nVerkäufer:\nPascal-K1N6\nZone:\nMechagon" }
