entries[167780] = { ["name"] = "Schuppenwachenkriegsbeinschützer der Zanj'ir", ["text"] = "Benthisch\nWird beim Aufheben gebunden\nBeine Platte\n19 Rüstung\n+7 [Stärke oder Intelligenz]\n+10 Ausdauer\n+ 8 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nAnlegen: Erhöht die Geschwindigkeit in Nazjatar und im Ewigen Palast um 6 .\nVerkaufspreis:" }
