entries[167782] = { ["name"] = "Schuppenwachengroßgürtel der Zanj'ir", ["text"] = "Benthisch\nWird beim Aufheben gebunden\nTaille Platte\n12 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\n+ 4 Vielseitigkeit\nHaltbarkeit 55 / 55\nAnlegen: Fügt Entartungen in Nazjatar und im Ewigen Palast 2% mehr Schaden zu.\nVerkaufspreis:" }
entries[167783] = { ["name"] = "Schuppenwachenarmschützer der Zanj'ir", ["text"] = "Benthisch\nWird beim Aufheben gebunden\nHandgelenk Platte\n11 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\n+ 3 Vielseitigkeit\nHaltbarkeit 55 / 55\nAnlegen: In Nazjatar und dem Ewigen Palast haben Eure Zauber und Fähigkeiten eine Chance, einen Kugelfisch zu beschwören, der nach 3 Sek. explodiert und Zielen innerhalb von 8 Metern um Euch 47 Schaden zufügt.\nVerkaufspreis:" }
