entries[167830] = { ["name"] = "Versteinerte kohlschwarze Schuppe", ["text"] = "Questgegenstand\n\"Enthält kondensierte Essenz, die einst einem schwarzen Drachen verliehen wurde, der vor Neltharion hier lebte...\"" }
entries[167831] = { ["name"] = "Smaragdsplitter", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Taucht die Smaragdsplitter ein, um einen mächtigen Gegenstand zu erschaffen.\n\"Fragmente der kondensierten Essenz des grünen Drachenschwarms.\"" }
entries[167832] = { ["name"] = "Elritzen in der Dose", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 20 Sek. ( 13200 / 5 * 20) Gesundheit und ( 8000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Eure Bewegungsgeschwindigkeit wird innerhalb von Mechagon 1 Stunde lang um 46 erhöht.\nVerkaufspreis:" }
entries[167833] = { ["name"] = "Klafterflossen", ["text"] = "Wird beim Aufheben gebunden\nHände Stoff\n3 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure Tempowertung um + 5.\n+ 2 Vielseitigkeit\nHaltbarkeit 55 / 55\nAnlegen: Gewährt Euch pro 10000 verbrauchtem Mana 8 Sek. lang einen Schild, der [ 15 * (1 + Vielseitigkeit)] Schaden absorbiert, bis maximal [ 147 * (1 + Vielseitigkeit)] Schaden.\nVerkaufspreis:" }
entries[167834] = { ["name"] = "Sturmgleiterschritte", ["text"] = "Wird beim Aufheben gebunden\nFüße Leder\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n+ 5 Vielseitigkeit\nHaltbarkeit 80 / 80\nAnlegen: Eure automatischen Angriffe gewähren Euch 15 Sek. lang 'Unberührbar' (bis zu 10 - mal stapelbar). 'Unberührbar' gewährt 1 kritischen Trefferwert. Jeglicher erlittene Schaden entfernt sämtliche Stapel von 'Unberührbar'.\nVerkaufspreis:" }
entries[167835] = { ["name"] = "Beinwickel des missgestalteten Herolds", ["text"] = "Wird beim Aufheben gebunden\nBeine Stoff\n5 Rüstung\n+6 Intelligenz\n+9 Ausdauer\nErhöht Eure kritische Trefferwertung um + 8.\nHaltbarkeit 120 / 120\nBenutzen: Öffnet für 12 Sek. einen Leerenriss unter Euch, der Euer Tempo um 26 erhöht. Wenn Ihr den Riss verlasst, bricht er Zusammen und Ihr erleidet 532 Schattenschaden. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[167836] = { ["name"] = "Bauplan: Elritzen in der Dose", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Durch die sorgfältige Konservierung bleibt der eklige Geschmack auf ewig erhalten.\"" }
entries[167837] = { ["name"] = "Sucherkette des Aufständischen", ["text"] = "Wird beim Aufheben gebunden\nTaille Kette\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 55 / 55\nAnlegen: Das Töten einer Entartung inspiriert 4 Verbündete und gewährt ihnen 20 Sek. lang 3 kritischen Trefferwert.\nVerkaufspreis:" }
entries[167838] = { ["name"] = "Gamaschen des abtrünnigen Gezeitenweisen", ["text"] = "Wird beim Aufheben gebunden\nBeine Leder\n8 Rüstung\n+6 [Beweglichkeit oder Intelligenz]\n+9 Ausdauer\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nAnlegen: Bei über 60% Gesundheit haben Eure Schadensfähigkeiten eine geringe Chance, Euer Ziel mit einem Blitz zu treffen, der [ 117 * (1 + Vielseitigkeit)] Naturschaden verursacht. Bei unter 60% Gesundheit haben Eure Schadensfähigkeiten eine geringe Chance, im Verlauf von 10 Sek. [ 32 * 6 * (1 + Vielseitigkeit)] Gesundheit wiederherzustellen.\nVerkaufspreis:" }
entries[167839] = { ["name"] = "Handschutz des verlorenen Verstands", ["text"] = "Wird beim Aufheben gebunden\nHände Kette\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nHaltbarkeit 55 / 55\nAnlegen: Bei über 90% Gesundheit haben Eure Schadensfähigkeiten eine sehr hohe Chance, Euch und Eurem Ziel 24 Schattenschaden zuzufügen.\nVerkaufspreis:" }
entries[167840] = { ["name"] = "Unsäglicher Schnallengürtel des Gedankendiebs", ["text"] = "Wird beim Aufheben gebunden\nTaille Platte\n12 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 55 / 55\nAnlegen: Wenn Eure Gesundheit unter 25% fällt, werdet Ihr sofort um [ 495 * (1 + Vielseitigkeit)] geheilt. Danach erleidet Ihr im Verlauf von 10 Sek. 495 Schattenschaden. Dieser Effekt kann nur einmal alle 3 Min. auftreten.\nVerkaufspreis:" }
entries[167841] = { ["name"] = "Stulpen des abyssischen Sprechers", ["text"] = "Wird beim Aufheben gebunden\nHände Platte\n12 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nHaltbarkeit 55 / 55\nAnlegen: Eure Fähigkeiten haben eine Chance, Euch einen Schild zu gewähren, der 1 Min. lang [ 442 * (1 + Vielseitigkeit)] Schaden absorbiert. Während der Schild hält, ist Euer Tempo um 11 erhöht.\nVerkaufspreis:" }
entries[167842] = { ["name"] = "Fathuuls Flutschützer", ["text"] = "Wird beim Aufheben gebunden\nBeine Kette\n12 Rüstung\n+6 [Beweglichkeit oder Intelligenz]\n+9 Ausdauer\nErhöht Eure Tempowertung um + 5.\nHaltbarkeit 120 / 120\nAnlegen: Bei über 90% Gesundheit haben Eure Schadensfähigkeiten eine hohe Chance, eine Welle auf Euer Ziel zu entfesseln, die [ 39 * (1 + Vielseitigkeit)] Frostschaden verursacht. Bei unter 90% Gesundheit haben Eure Schadensfähigkeiten eine hohe Chance, [ 59 * (1 + Vielseitigkeit)] Gesundheit wiederherzustellen.\nVerkaufspreis:" }
