entries[167863] = { ["name"] = "Säule der ertränkten Kabale", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n7 - 10 Schaden Geschwindigkeit 3.60\n(2.4 Schaden pro Sekunde)\n+28 Intelligenz\n+9 Ausdauer\nHaltbarkeit 120 / 120\nBenutzen: Legt für 1.5 Min. einen Schutz über Euer Ziel. Wenn es durch einen einzigen Treffer 325 Schaden erleidet, heilt der Schutz das Ziel um [ 325 * (1 + Vielseitigkeit)] und schwindet. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[167864] = { ["name"] = "Dreizack der Tiefsee", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n11 - 22 Schaden Geschwindigkeit 3.60\n(4.6 Schaden pro Sekunde)\n+9 Ausdauer\nHaltbarkeit 120 / 120\nAnlegen: Erlittener Schaden hat eine geringe Chance, für 40 Sek. eine schützende Blase um Euch zu bilden, die 25% des eintreffenden Schadens absorbiert [maximal ( 227 * (1 + Vielseitigkeit))]. Wenn die Blase platzt, wird Euer Primärwert 1 Min. lang um 3 erhöht. Bis zu 3-mal stapelbar.\nVerkaufspreis:" }
entries[167865] = { ["name"] = "Leerenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\nBenutzen: Hüllt ein verbündetes Ziel 12 Sek. lang in Dunkelheit und absorbiert eintreffenden Schaden oder Heilung in Höhe von [ 790 * (1 + Vielseitigkeit)]. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[167866] = { ["name"] = "Des Lauerers tückisches Geschenk", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 [Beweglichkeit oder Stärke]\nBenutzen: Nehmt 'N'Zoths Gabe' an, wodurch Eure Meisterschaft 30 Sek. lang um 43 erhöht wird. Währenddessen werdet Ihr alle 1 Sek. mit 'Leid' belegt, was 3 Schattenschaden pro Stapel verursacht. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[167867] = { ["name"] = "Unergründlicher Wille des Vorboten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\nAnlegen: Eure Schadensfähigkeiten haben eine Chance, einen Speer des Vergessens auf Euer Ziel zu schleudern, der ihm 124 Schattenschaden zufügt. Beim Einschlag zersplittert der Speer in Eure Richtung und belegt Euch für 1.5 Sek. mit einem Stilleeffekt, falls Ihr getroffen werdet.\nVerkaufspreis:" }
entries[167868] = { ["name"] = "Götze des willkürlichen Verschlingens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 [Beweglichkeit oder Stärke]\nBenutzen: Nährt Euch an sieben Verbündeten oder Gegnern innerhalb von 15 Metern. Entzieht jedem 47 Gesundheit und heilt Euch um 250% des Schadens. (1 Min Abklingzeit)\nVerkaufspreis:" }
