entries[168021] = { ["name"] = "Nullifizierertransportrelais", ["text"] = "Wird beim Aufheben gebunden\n\"Platziert das Nullifizierertransportrelais an einem sicheren Ort.\"" }
entries[168022] = { ["name"] = "Pläne: Khaz'gorischer Schmiedehammer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Khaz'gorischen Schmiedehammers.\nErschafft einen khaz'gorischen Hammer.\nBenötigt Schmiedekunst von Kul Tiras (150)\nVerkaufspreis:\nKhaz'gorischer Schmiedehammer\nWird beim Aufheben gebunden\nEinzigartig\nWerkzeug für Schmiedekunst Beim Erschaffen von Schmiederüstung oder -waffen besteht eine Chance, dass sie mit der Eigenschaft 'Unzerstörbar' belegt werden.\nBenutzen: Gestattet es dem Benutzer, einen Ausrüstungsgegenstand sofort zu reparieren. (1 Stunde Abklingzeit)\nAnlegen: +4 Schmiedekunstfertigkeit.\nBenötigt Schmiedekunst von Kul Tiras (150)\n\"Dieser Hammer kann anstelle eines normalen Schmiedehammers für Handwerksprojekte verwendet werden.\"\nBenötigt Blut des Titanen (30), Werkzeuge zum Präzisionssegnen , Azerokks Faust , Sturmsilbererz (30), Platinerz (20), Expulsom (10)" }
entries[168024] = { ["name"] = "Formel: Iwens Verzauberungsrute", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung einer Iwens Verzauberungsrute.\nStellt Iwens Verzauberungsrute her.\nBenötigt Verzauberkunst von Kul Tiras (150)\nVerkaufspreis:\nIwens Verzauberungsrute\nWird beim Aufheben gebunden\nEinzigartig\nGewährt beim Entzaubern zusätzliche Ressourcen.\nBenutzen: Verbraucht einen trüben Kristall, um einen inaktiven Golem zum Leben zu erwecken. (5 Sek. Abklingzeit)\nBenötigt Verzauberkunst von Kul Tiras (150)\n\"Vor lauter Drustmagie surrt diese Rute. Kann auch wie jede geringere runenverzierte Rute verwendet werden.\"\nBenötigt Greifender Weidenarm , Runenstein von Thros , Verweilende Drustessenz (50), Umbralsplitter (20), Trüber Kristall (10), Expulsom (10)" }
entries[168025] = { ["name"] = "Bauplankompendium: Üb3r-Schrauber", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erlernt alle Ingenieurskunstbaupläne neu, die Ihr durch das Erfüllen von Quests für Euer Handwerkszeug erhalten, aber nach einem Berufswechsel vergessen habt.\nBenötigt Ingenieurskunst von Kul Tiras (150)\nVerkaufspreis:" }
entries[168026] = { ["name"] = "Buch der Techniken: Lana'thels blutiger Federkiel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erlernt alle Inschriftentechniken neu, die Ihr durch das Erfüllen von Quests für Euer Handwerkszeug erhalten, aber nach einem Berufswechsel vergessen habt.\nBenötigt Inschriftenkunde von Kul Tiras (150)\nVerkaufspreis:" }
entries[168027] = { ["name"] = "Vorlage: Fokus des Juwelenhammers", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Fokus des Juwelenhammers.\nSchleift eine Fokuslinse.\nBenötigt Juwelierskunst von Kul Tiras\n(150)\nVerkaufspreis:\nFokus des Juwelenhammers\nWird beim Aufheben gebunden\nEinzigartig\nErmöglicht dem Träger, mit Schreinen in Kul Tiras und Zandalar zu interagieren. Er kann das Licht der Zone mithilfe der Linse bündeln und so eine Edelsteingeode erschaffen.\nBenutzen: Entfernt mithilfe des Fokus sorgfältig einen gesockelten Edelstein aus einem Eurer Gegenstände.\nBenötigt Juwelierskunst von Kul Tiras\n(150)\nBenötigt Harlans diamantenübersätes Fernrohr , Unbearbeitete Azeritgeode , Feines Azeritpulver (50), Krakenauge (5), Expulsom (10)" }
entries[168028] = { ["name"] = "Muster: Schlägel der donnernden Häute", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Schlägels der donnernden Häute.\nStellt einen Schlägel der donnernden Häute her.\nBenötigt Lederverarbeitung von Kul Tiras (150)\nVerkaufspreis:\nSchlägel der donnernden Häute\nWird beim Aufheben gebunden\nEinzigartig\nErmöglicht Euch, mit Trommeln der Urmacht zu interagieren, die Euch mit Geschwindigkeit, Macht oder Widerstandskraft segnen.\nBenutzen: Erhöht Euer Tempo um 15%. Hält 40 Sek. lang an.\n\nWenn der Effekt endet, seid Ihr erschöpft und könnt 10 Min. lang nicht mehr von 'Kampfrausch', 'Heldentum' oder 'Zeitkrümmung' profitieren. (10 Min Abklingzeit)\nBenötigt Lederverarbeitung von Kul Tiras (150)\n\"Nützlich zur Formung von Lederstücken und als Schlaginstrument.\"\nBenötigt Lange majestätische Sehne (4), Geist des Geschlagenen (15), Blutbefleckter Knochen (50), Sturmbalg (50), Gehärteter Sturmbalg (25), Expulsom (10)" }
entries[168029] = { ["name"] = "Muster: Synchronfaden", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Synchronfadens.\nSynchronfaden herstellen.\nBenötigt Schneiderei von Kul Tiras (150)\nVerkaufspreis:\nSynchronfaden\nWird beim Aufheben gebunden\nEinzigartig\nIn der Zeit verschobener Stoff aus Kul Tiras und Zandalar erscheint öfter in der Welt.\nBenutzen: Ermöglicht Synchronschneidern, in Kul Tiras und Zandalar Risse im Gewebe der Zeit zu flicken.\nBenötigt Schneiderei von Kul Tiras (150)\n\"Ein Stich zur rechten Zeit sorgt dafür, dass die Welt nicht auseinanderfällt.\"\nBenötigt Essenz der Trolldynastie , Essenz des majestätischen Loa , Essenz der Tiefen , Essenz der Sande , Gischtvernebeltes Leinen (75), Nylonfaden (75), Expulsom (10)" }
entries[168035] = { ["name"] = "Schlundrattengeschirr", ["text"] = "Torghast, Turm der Verdammten\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verwandelt Euch in eine Schlundratte, während Ihr in Torghast seid, was Eure Bewegungsgeschwindigkeit um 100% erhöht." }
