entries[168125] = { ["name"] = "Runenstein von Thros", ["text"] = "Wird beim Aufheben gebunden\n\"Gorak Tul war auf Azeroth der erste, der mit diesem Stein mühevolle wie mächtige Verzauberungen erzeugte.\"\nVerkaufspreis:" }
entries[168126] = { ["name"] = "Greifender Weidenarm", ["text"] = "Wird beim Aufheben gebunden\n\"Die stärksten Golems des Herzbannzirkels bergen auch nach ihrer Zerstörung noch einen Teil ihrer Lebenskraft.\"\nVerkaufspreis:" }
entries[168127] = { ["name"] = "Verweilende Drustessenz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (50)\n\"Sie findet sich in den meisten uralten Drustfeinden und in konzentrierterer Form in jenen von ihnen, die das Kronsteiganwesen bewohnen.\"\nVerkaufspreis:" }
entries[168128] = { ["name"] = "Essenz des majestätischen Loa", ["text"] = "Wird beim Aufheben gebunden\n\"Rezan diente den Königen der Zandalari über Jahrtausende.\"\nVerkaufspreis:" }
entries[168129] = { ["name"] = "Essenz der Trolldynastie", ["text"] = "Wird beim Aufheben gebunden\n\"Dazar war der erste und Rastakhan wird nicht der letzte sein.\"\nVerkaufspreis:" }
entries[168130] = { ["name"] = "Essenz der Tiefen", ["text"] = "Wird beim Aufheben gebunden\n\"Kraken wie Viq'Goth lebten in den Tiefen, lange bevor die Völker Azeroths überhaupt ihre Zehen ins Wasser der Ozeane steckten.\"\nVerkaufspreis:" }
entries[168131] = { ["name"] = "Essenz der Sande", ["text"] = "Wird beim Aufheben gebunden\n\"Sethraliss' Opfer in Vol'dun bewahrte Azeroth vor einem schlimmen Schicksal, aber es bedeutete den Untergang ihrer Dschungelheimat.\"\nVerkaufspreis:" }
entries[168132] = { ["name"] = "Harlans diamantenübersätes Fernrohr", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[168133] = { ["name"] = "Unbearbeitete Azeritgeode", ["text"] = "Wird beim Aufheben gebunden\n\"Das leuchtende Herz von Azerokk.\"\nVerkaufspreis:" }
entries[168134] = { ["name"] = "Feines Azeritpulver", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (50)\n\"Es ist schwer, in Pulverform zu finden, aber die Angestellten der Aschenwind & Co., die mit Azerit arbeiten, könnten etwas dabei haben.\"\nVerkaufspreis:" }
entries[168135] = { ["name"] = "Blut des Titanen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (30)\n\"Kommt in einigen der größten Azeritansammlungen vor.\"\nVerkaufspreis:" }
entries[168136] = { ["name"] = "Azerokks Faust", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[168137] = { ["name"] = "Werkzeuge zum Präzisionssegnen", ["text"] = "Wird beim Aufheben gebunden\n\"Die Segen, mit denen der Rat der Gezeitenweisen die Schiffe der Kul Tiraner segnet, müssen mit äußerster Präzision gesprochen werden. Eben diese Präzision muss auch beim Hammer angewendet werden, wenn wir nicht versehentlich ein Loch in Azeroth hauen wollen.\"\nVerkaufspreis:" }
entries[168138] = { ["name"] = "Geist des Geschlagenen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (15)\n\"Die Geister der verschiedenen seltenen Tiere von Kul Tiras und Zandalar können im beherzten Kampf errungen werden.\"\nVerkaufspreis:" }
entries[168139] = { ["name"] = "Lange majestätische Sehne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (4)\n\"Die Sehnen, die sich noch immer an wiedererweckten Teufelssauriern befinden, suchen bezüglich Belastbarkeit und Klangfarbe ihresgleichen.\"\nVerkaufspreis:" }
entries[168140] = { ["name"] = "Uralte Blutpigmente", ["text"] = "Wird beim Aufheben gebunden\n\"Findet sich im Blut der großen Bedrohungen, die durch Kul Tiras und Zandalar streifen.\"\nVerkaufspreis:" }
entries[168141] = { ["name"] = "Eisversiegelte uralte Blutpigmente", ["text"] = "Wird beim Aufheben gebunden\nDauer: 1 tag (Realzeit)\n\"Es schmilzt langsam.\"\nVerkaufspreis:" }
entries[168142] = { ["name"] = "Geronnenes Miasma", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (50)\n\"Das verderbte Blut des Tiefenpfuhls hat die einzigartige Eigenschaft, dass es von Natur aus niemals trocknet.\"\nVerkaufspreis:" }
entries[168143] = { ["name"] = "Penetrant potenter Trank", ["text"] = "Wird beim Aufheben gebunden\n\"Die Tränke des Herzbannzirkels im Kronsteiganwesen sind besonders interessant.\"\nVerkaufspreis:" }
entries[168144] = { ["name"] = "Extrem präzise Phiole", ["text"] = "Wird beim Aufheben gebunden\n\"Um das Potenzial des RIESENFLÖZ anzuzapfen, bedarf es präziser Instrumente.\"\nVerkaufspreis:" }
entries[168145] = { ["name"] = "Karaffe des verschlagenen Schurken", ["text"] = "Wird beim Aufheben gebunden\n\"Trotz so mancher Kerkerhaft und anderen Strapazen hat Jes Knurris es irgendwie geschafft, im Besitz dieser erstaunlich unauffälligen Karaffe zu bleiben.\"\nVerkaufspreis:" }
entries[168146] = { ["name"] = "Sphäre aus Sangaurum", ["text"] = "Wird beim Aufheben gebunden\n\"Priesterin Alun'za verwendet die Sphäre nur bei den wichtigsten Ritualen.\"\nVerkaufspreis:" }
entries[168152] = { ["name"] = "Miniaturisierter Kraftkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (2)\n\"Ist in Säbeltronmodellen eingebaut, die im nordwestlichen Sturmsangtal und auf dem verlassenen Schrottplatz eingesetzt werden.\"\nVerkaufspreis:" }
entries[168153] = { ["name"] = "Münzenauswerfer", ["text"] = "Wird beim Aufheben gebunden\n\"Das Modell aus dem münzbetriebenen Meuteverprügler, eignet sich hervorragend als An-/Ausschalter.\"\nVerkaufspreis:" }
entries[168154] = { ["name"] = "Statische Induktionsmatrix", ["text"] = "Wird beim Aufheben gebunden\n\"Nur die größten Bltzelementare im Tempel von Sethraliss können eine stabile Matrix erzeugen.\"\nVerkaufspreis:" }
entries[168155] = { ["name"] = "Köder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ein stinkender Haufen eigenartigen Fleischs.\"" }
entries[168157] = { ["name"] = "Schimmerndes Aalleder", ["text"] = "Questgegenstand\nEinzigartig\n\"Die schleimüberzogene Haut glitzert und glänzt.\"" }
entries[168158] = { ["name"] = "Verzauberte Perle", ["text"] = "Questgegenstand\n\"Eine mit dem uraltem Mana aus dem Brunnen der Ewigkeit versetzte Perle.\"" }
entries[168159] = { ["name"] = "Köder", ["text"] = "Questgegenstand\nEinzigartig (10)\nBenutzen: Wirft einen Haufen Köder ins Wasser." }
entries[168160] = { ["name"] = "Juwelenbesetzte Skarabäusfigur", ["text"] = "Wird beim Aufheben gebunden\n\"Der zuvor belebte Skarabäus erstarrt zu einer Figur, wenn man ihn berührt.\"" }
entries[168161] = { ["name"] = "Abgeworfener Panzer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Rutscht auf dem Panzer herum. (10 Sek. Abklingzeit)\n\"Makrura geben beim Panzerwechsel ein zähflüssiges Sekret ab. Es befindet sich noch eine Menge davon im Panzer.\"\nVerkaufspreis:" }
entries[168162] = { ["name"] = "Chronotruhe mit Stoffen", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält Stoffe aus der fernen Vergangenheit oder vielleicht der Gegenwart, möglicherweise sogar der Zukunft?\"\n<Zum Öffnen rechtsklicken>" }
entries[168167] = { ["name"] = "Messingschlüssel", ["text"] = "Questgegenstand\n\"Die Kerben des Schlüsselblatts haben unter dem Alter gelitten.\"" }
entries[168168] = { ["name"] = "Vergoldete Feder", ["text"] = "Wird beim Aufheben gebunden\n\"Zu finden bei den legendenumwobenen goldenen Schlangen von Königsruh.\"\nVerkaufspreis:" }
entries[168169] = { ["name"] = "Uralte Schriftrolle", ["text"] = "Questgegenstand\n\"Eine magische Verzauberung hat diese uralten Schriftrollen jahrtausendelang vor Schäden bewahrt.\"" }
entries[168170] = { ["name"] = "Arkaner Foliant", ["text"] = "Questgegenstand\n\"Diese Folianten in altem Elfisch scheinen unbezahlbare Geheimnisse des Arkanen zu enthalten.\"" }
entries[168173] = { ["name"] = "Kelpbeere", ["text"] = "Questgegenstand\nEinzigartig (8)\n\"Diese salzigen Schönheiten verbinden pikante und süße Aromen mit einem Hauch von Säure zu einem unvergesslichen Wein und einem leckeren Snack.\"" }
entries[168174] = { ["name"] = "Fass Kelpbeerensaft", ["text"] = "Questgegenstand\nEinzigartig\n\"Diese Fässer verleihen darin gelagertem Kelpbeerenwein einen vollmundigen Geschmack.\"" }
