entries[168271] = { ["name"] = "Gestohlenes Banner von Ramkahen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Platziert eine Schlachtstandarte von Ramkahen in der Nähe des Ziels, die 3 Legionäre von Ramkahen beschwört, die es angreifen. Funktioniert nur in Uldum.\nVerkaufspreis:" }
entries[168273] = { ["name"] = "Zittergiftarmbrust", ["text"] = "Wird beim Aufheben gebunden\nDistanz Armbrust\n12 - 19 Schaden Geschwindigkeit 3.00\n(5.2 Schaden pro Sekunde)\n+7 Beweglichkeit\n+10 Ausdauer\nErhöht Eure kritische Trefferwertung um + 7.\nHaltbarkeit 120 / 120\nAnlegen: Eure Schaden verursachenden Fähigkeiten haben eine Chance, [ 34 * (1 + Vielseitigkeit)] Naturschaden zu verursachen. Wenn ein Verbündeter Euer Ziel mit 'Zittergift' belegt hat, erleidet dieses zusätzlich [ 24 * (1 + Vielseitigkeit)] Frostschaden.\nVerkaufspreis:" }
