entries[168275] = { ["name"] = "Anu-Azshara, Stab der Ewigen", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n7 - 11 Schaden Geschwindigkeit 3.60\n(2.5 Schaden pro Sekunde)\n+30 Intelligenz\n+10 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nAnlegen: Eure Zauber haben eine Chance, Euch eine Aufladung von 'Potenz' zu gewähren. Wenn Eure Gesundheit oder Euer Mana unter 10% fällt, wird 'Potenz' ausgelöst. Innerhalb von 40 Metern erleiden Gegner dadurch Schaden und Verbündete werden geheilt, jeweils in Höhe von [ 8 * (1 + Vielseitigkeit)] pro Aufladung.\nVerkaufspreis:" }
