entries[168328] = { ["name"] = "Verhärtete Azeritformation", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Azeroths unsterbliches Geschenk'.\nGroße Macht:\nAzeroths unsterbliches Geschenk\nSofort 1 min Abklingzeit Verringert 4 Sek. lang sämtlichen von Euch erlittenen Schaden um 20%.\nGeringe Macht:\nVerhärtetes Azerit\nWenn Eure Gesundheit unter 35% fällt, erhaltet Ihr 8 Sek. lang 799 Rüstung.\n\nDieser Effekt kann nur einmal alle 150 Sek. auftreten. (2.5Min. Abklingzeit)" }
entries[168329] = { ["name"] = "Schlüssel für das Modell W", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man ein Mechamotorrad Modell W beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die rasante technologische Entwicklung bei den Nachfahren von Mimiron begann mit dem Einsatz eines neuen Getriebes, das zu solchen Wundern wie dem tragischerweise unterproduzierten Modell W führte.\"\nErfolg:\nMecha-fertig\nKategorie:\nBattle for Azeroth" }
entries[168330] = { ["name"] = "Rezept: Mech-Dowels \"Big Mech\"", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Mech-Dowels 'Big Mech' effektiver herstellt.\nIhr verschwendet nichts von Euren Zutaten und stellt so bei jeder Zubereitung viel mehr von Mech-Dowels \"Big Mech\" her.\nBenötigt Kochkunst von Kul Tiras (170)\nVerkaufspreis:\nMech-Dowels \"Big Mech\"\nBenutzen: Stellt im Verlauf von 20 Sek. 50769 Gesundheit und 30769 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 43 kritischen Trefferwert.\nVerkaufspreis:\nBenötigt Ersatzteile (5), Ionisierte Elritze (8), Wildes Mehl (5), Fusaka (3)" }
