entries[168370] = { ["name"] = "Rostige Schlüssel für den Schrotthaufendrifter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Schrotthaufendrifter beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wenn Ihr wirklich auffallen wollt... und kein Problem damit habt, Euch in dieses riesige, fast auseinanderfallende Rad zu schnallen.\"\nBeute von:\nRostfeder\nZone:\nMechagon" }
