entries[168391] = { ["name"] = "Umhang der schlechten Neuigkeiten", ["text"] = "Wird beim Aufheben gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 5.\nVerkaufspreis:" }
entries[168392] = { ["name"] = "Rochensushi", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 10000 * 20 / 5) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[168393] = { ["name"] = "Holografische Kampfentitätendaten", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: In einem experimentellen holografischen Entitätenmaterialisierer installieren, um auf gespeicherte Daten zuzugreifen.\n\"#WARNUNG 2.1.7 - B: Enthält Daten für anspruchsvolle Kampftrainingssimulation. Installation auf eigene Gefahr.\"" }
entries[168394] = { ["name"] = "Kasten mit Einzelteilen", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[168395] = { ["name"] = "Verstrahlter Kasten mit Einzelteilen", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[168396] = { ["name"] = "Angriffspläne", ["text"] = "Questgegenstand\n\"Diese Marschbefehle für die Soldaten der Naga sind von Königin Azshara unterschrieben.\"" }
entries[168397] = { ["name"] = "Reißzahn des Ungetüms", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Dolch\n2 - 4 Schaden Geschwindigkeit 1.80\n(1.7 Schaden pro Sekunde)\n+20 Intelligenz\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\n+ 5 Vielseitigkeit\nHaltbarkeit 80 / 80\nVerkaufspreis:" }
entries[168398] = { ["name"] = "Foliant der Bindung", ["text"] = "Questgegenstand\n\"Der uralte Text enthält verbotene Rituale zur Unterwerfung der Elemente.\"" }
entries[168399] = { ["name"] = "Fetisch der Dunkelhöhlen", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Anima von Leben und Tod'.\nGroße Macht:\nAnima des Todes\nSofort 2.5 min Abklingzeit Ihr wendet Eure Lebenskraft auf, um Gegner zu verbrennen. Dadurch erleiden alle Gegner in der Nähe Feuerschaden in Höhe von 10% Eurer maximalen Gesundheit und Ihr werdet pro getroffenem Gegner um 5% Eurer maximalen Gesundheit geheilt, bis zu 25% Eurer maximalen Gesundheit.\nGeringe Macht:\nAnima des Lebens\nAzeritenergie strömt durch Eure Adern und erhöht Eure maximale Gesundheit alle 5 Sek. um 244 . Bis zu 10-mal stapelbar.\n\nDieser Effekt endet, wenn Eure Gesundheit unter 35% fällt." }
entries[168400] = { ["name"] = "Nullkraftsicherheitsbehälter", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Nullifikationsdynamo'.\nErfordert einen freundlichen Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nVerstärkte Nullbarriere\nSofort 3 min Abklingzeit Gewährt eine verstärkte Nullbarriere, die 10 Sek. lang [ 11391 * (1 + Vielseitigkeit)] Magieschaden absorbiert.\nGeringe Macht:\nNullbarriere\nGewährt alle 20 Sek. eine Nullbarriere, die 10 Sek. lang [ 2268 * (1 + Vielseitigkeit)] Magieschaden absorbiert.\n\"Es scheint absolut keine Energie oder Materie enthalten zu sein, und doch ist er deutlich schwerer als der Sicherheitsbehälter selbst.\"" }
entries[168404] = { ["name"] = "Giftbenetzte Fangzähne", ["text"] = "Questgegenstand\nEinzigartig" }
entries[168406] = { ["name"] = "Gefangener Freund", ["text"] = "Questgegenstand\n\"Von innen ist vergnügtes Quieken zu hören.\"" }
entries[168407] = { ["name"] = "Freundschaftsnetz", ["text"] = "Questgegenstand\nBenutzen: Macht einen Gegner bewegungsunfähig und nimmt ihn gefangen. (3 Sek. Abklingzeit)" }
entries[168408] = { ["name"] = "Spross von Torcali", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Tochter des großen Terrorhornloas, Torcali, glaubte stets fest daran, dass ihr Hüter ihr helfen würde, zu ihrem vollen Potenzial heranzuwachsen.\"\nQuest:\nNie allein auf Reisen\nZone:\nZuldazar" }
entries[168409] = { ["name"] = "Geschmeidige Bälge", ["text"] = "Questgegenstand\nEinzigartig (12)\n\"Die besten der seltenen Bälge, die Ihr erworben habt. Sie wurden eingeweicht, damit sie schön geschmeidig sind.\"" }
entries[168410] = { ["name"] = "Erste-Hilfe-Kasten", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Verbindet verletzte Expeditionsmitglieder und hilft ihnen so wieder auf die Beine." }
entries[168412] = { ["name"] = "Leichtlaufhufplatten", ["text"] = "Benutzen: Im Reittierausrüstungsplatz anlegen, um die Geschwindigkeit Eures Reittiers am Boden um 20% zu erhöhen. Funktioniert nicht auf Schlachtfeldern oder in Arenen und ist nicht mit anderen Effekten zur Erhöhung der Reitgeschwindigkeit stapelbar.\nVerkaufspreis:" }
entries[168416] = { ["name"] = "Wasserschreiter des Anglers", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nBenutzen: Im Reittierausrüstungsplatz anlegen, um während des Reitens über Wasser wandeln zu können. Jeglicher Schaden hebt den Effekt auf. Funktioniert nicht auf Schlachtfeldern oder in Arenen.\nVerkaufspreis:" }
entries[168417] = { ["name"] = "Aufblasbare Reittierschuhe", ["text"] = "Aufblasbare Reittierschuhe\nBenutzen: Im Reittierausrüstungsplatz anlegen, um während des Reitens über Wasser wandeln zu können. Jeglicher Schaden hebt den Effekt auf. Funktioniert nicht auf Schlachtfeldern oder in Arenen.\nVerkaufspreis:" }
entries[168419] = { ["name"] = "Bequemes Reitgeschirr", ["text"] = "Benutzen: Im Reittierausrüstungsplatz anlegen, um während des Reitens nicht benommen gemacht werden zu können. Funktioniert nicht auf Schlachtfeldern oder in Arenen.\nVerkaufspreis:" }
entries[168421] = { ["name"] = "Tiefenrochenei", ["text"] = "Questgegenstand" }
entries[168425] = { ["name"] = "Schwimmstrahl", ["text"] = "Questgegenstand\nBenutzen: Ein Wasserschwall schießt den Benutzer nach oben und ermöglicht ihm für 6 Sek. das Schweben. (7 Sek. Abklingzeit)\n\"Kann nur beim Korallenwald genutzt werden.\"" }
entries[168427] = { ["name"] = "Sattelfallschirm", ["text"] = "Benutzen: Im Reittierausrüstungsplatz anlegen, um einen Rettungsfallschirm anzubringen, der zum Einsatz kommt, wenn Ihr hoch in der Luft absitzt. Funktioniert nicht auf Schlachtfeldern oder in Arenen.\nVerkaufspreis:" }
entries[168430] = { ["name"] = "Kloppertopps Wumme", ["text"] = "Questgegenstand\nBenutzen: Feuert eine Raketensalve auf eine Sicherungskiste von Mechagon." }
entries[168432] = { ["name"] = "Frischer Schwamm", ["text"] = "Questgegenstand\nBenutzen: Schwammsporen zerstreuen sich beim Aufprall und bewegen sich zum nächsten verstohlenen Naga. (5 Sek. Abklingzeit)\n\"Kann nur beim Hängenden Riff genutzt werden.\"" }
entries[168433] = { ["name"] = "Schlotkelpspross", ["text"] = "Questgegenstand\nEinzigartig (10)\n\"Wird zum Heilen, Kochen, Lindern von Beschwerden und Brauen genutzt...\"" }
entries[168435] = { ["name"] = "Ferngesteuerte Schaltkreisüberbrückung", ["text"] = "Blaue Lochkarte\nWird beim Aufheben gebunden\nAnlegen: Ihr könnt manche Kreaturen und Konstrukte in Mechagon hacken.\nVerkaufspreis:" }
entries[168436] = { ["name"] = "Konzentrierte Sternenspitze", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Geist der Bewahrung'.\nGroße Macht:\nGeist der Bewahrung\n40 Meter Reichweite Kanalisiert (Wirken in 3 sek.) 1 min Abklingzeit Kanalisiert einen Energiestrahl auf einen Verbündeten und heilt ihn im Verlauf von 3 Sek. um [( 1452 * (5) + 1452 ) * (1 + Vielseitigkeit)] Gesundheit.\nGeringe Macht:\nErgebener Geist\nErhaltet alle 5 Sek. 'Ergebener Geist, wodurch Euer nächster Einsatz von ' Schnellheilung ' um zusätzlich 153 Gesundheit heilt. Bis zu 3-mal stapelbar.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[168439] = { ["name"] = "Wirbelnder Sternenstaub", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Geist der Bewahrung'.\nGroße Macht:\nGeist der Bewahrung\n40 Meter Reichweite Kanalisiert (Wirken in 3 sek.) 1 min Abklingzeit Kanalisiert einen Energiestrahl auf einen Verbündeten und heilt ihn im Verlauf von 3 Sek. um [( 1452 * (5) + 1452 ) * (1 + Vielseitigkeit)] Gesundheit. Bis zu 6 andere Verbündete im Strahl werden alle 0.6 Sek. um [ 145 * (1 + Vielseitigkeit)] Gesundheit geheilt.\nGeringe Macht:\nErgebener Geist\nErhaltet alle 5 Sek. 'Ergebener Geist', wodurch Euer nächster Einsatz von ' Schnellheilung ' um zusätzlich 153 Gesundheit heilt. Bis zu 5-mal stapelbar.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[168440] = { ["name"] = "Schimmernder Sternensplitter", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Geist der Bewahrung'.\nErlernt Rang 3 einer Essenz von den Rajani oder dem Abkommen von Uldum auf einem anderen Charakter, um diese Essenz freizuschalten.\nBenötigt einen respektvollen Ruf bei den Rajani. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nGeist der Bewahrung\n40 Meter Reichweite Kanalisiert (Wirken in 3 sek.) 1 min Abklingzeit Kanalisiert einen Energiestrahl auf einen Verbündeten und heilt ihn im Verlauf von 3 Sek. um [( 1452 * (5) + 1452 ) * (1 + Vielseitigkeit)] Gesundheit. Bis zu 6 andere Verbündete im Strahl werden alle 0.6 Sek. um [ 145 * (1 + Vielseitigkeit)] Gesundheit geheilt.\n\nImmer wenn 'Geist der Bewahrung' das Primärziel heilt, erhaltet Ihr einen Stapel von 'Ergebener Geist'.\nGeringe Macht:\nErgebener Geist\nErhaltet alle 5 Sek. 'Ergebener Geist, wodurch Euer nächster Einsatz von ' Schnellheilung ' um zusätzlich 153 Gesundheit heilt. Bis zu 5-mal stapelbar.\n\nJeder verbrauchte Stapel von 'Ergebener Geist' erhöht die kritische Trefferchance Eures nächsten Einsatzes von ' Schnellheilung ' innerhalb von 15 Sek. um 20%.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[168442] = { ["name"] = "Brodelndes Blut der Bezwungenen", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Blut des Feindes'.\nGroße Macht:\nBlut des Feindes\nSofort 2 min Abklingzeit Das Herz von Azeroth fügt Gegnern innerhalb von 12 Metern durch eine heftige Explosion 1739 Schattenschaden zu. Ihr gewinnt 10 Sek. lang 25% kritische Trefferchance gegen die Ziele hinzu .\nGeringe Macht:\nBlutgetränkt\nEure kritischen Treffer mit Zaubern und Fähigkeiten gewähren Euch einen Stapel von 'Blutgetränkt'. Bei 40 Stapeln erhaltet Ihr 8 Sek. lang 125 Tempo." }
entries[168443] = { ["name"] = "Aufgewühltes Blut der Beherrschten", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Blut des Feindes'.\nErfordert den Erfolg \"Schlachtfeldraufbold\". (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nBlut des Feindes\nSofort 1.5 min Abklingzeit Das Herz von Azeroth fügt Gegnern innerhalb von 12 Metern durch eine heftige Explosion 1739 Schattenschaden zu. Ihr gewinnt 10 Sek. lang 25% kritische Trefferchance gegen die Ziele hinzu.\nGeringe Macht:\nBlutgetränkt\nEure kritischen Treffer mit Zaubern und Fähigkeiten gewähren Euch einen Stapel von 'Blutgetränkt'. Bei 40 Stapeln erhaltet Ihr 8 Sek. lang 125 Tempo.\n\nJeder Stapel von 'Blutgetränkt' gewährt 2 kritischen Trefferwert." }
entries[168444] = { ["name"] = "Brodelndes Blut der Eroberten", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Blut des Feindes'.\nErfordert den Erfolg \"Schlachtfeldtaktiker\". (Kauf nicht möglich, wenn bereits bekannt)\nErlernt Rang 3 vom Blut des Feindes, des Kunstwerks der Zeit oder der Sphäre der Unterdrückung auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\nBlut des Feindes\nSofort 1.5 min Abklingzeit Das Herz von Azeroth fügt Gegnern innerhalb von 12 Metern durch eine heftige Explosion 1739 Schattenschaden zu. Ihr erhaltet 10 Sek. lang 25% zusätzliche kritische Trefferchance gegen die Ziele und Euer kritischer Trefferschaden wird 5 Sek. lang um 25% erhöht.\nGeringe Macht:\nBlutgetränkt\nEure kritischen Treffer mit Zaubern und Fähigkeiten gewähren Euch einen Stapel von 'Blutgetränkt'. Jeder Stapel von 'Blutgetränkt' erhöht den kritischen Trefferwert um 2 . Bei 40 Stapeln erhaltet Ihr 8 Sek. lang 125 Tempo.\n\nEs besteht eine Chance von 25%, dass 'Blutgetränkt' nur 30 Stapel verbraucht." }
entries[168445] = { ["name"] = "Zauberstab der Überflutung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Erschafft einen Wasserguss in einem Bereich, um Feuer zu löschen." }
entries[168446] = { ["name"] = "Ring - Bündnis des kritischen Trefferwerts", ["text"] = "Benutzen: Einen Ring dauerhaft verzaubern, sodass der kritische Trefferwert um 28 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:" }
