entries[168450] = { ["name"] = "Formel: Ring - Bündnis des kritischen Trefferwerts", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man 'Bündnis des kritischen Trefferwerts' effizienter verzaubert.\nEinen Ring dauerhaft verzaubern, sodass der kritische Trefferwert um 28 erhöht wird. Materialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (1)\nVerkaufspreis:" }
entries[168451] = { ["name"] = "Formel: Ring - Bündnis des Tempos", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man 'Bündnis des Tempos' effizienter verzaubert.\nEinen Ring dauerhaft verzaubern, sodass das Tempo um 28 erhöht wird. Materialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (1)\nVerkaufspreis:" }
entries[168452] = { ["name"] = "Formel: Ring - Bündnis der Meisterschaft", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man 'Bündnis der Meisterschaft' effizienter verzaubert.\nEinen Ring dauerhaft verzaubern, sodass die Meisterschaft um 28 erhöht wird. Materialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (1)\nVerkaufspreis:" }
entries[168453] = { ["name"] = "Formel: Ring - Bündnis der Vielseitigkeit", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man 'Bündnis der Vielseitigkeit' effizienter verzaubert.\nEinen Ring dauerhaft verzaubern, sodass die Vielseitigkeit um 28 erhöht wird. Materialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (1)\nVerkaufspreis:" }
