entries[168478] = { ["name"] = "Schiffbrecher der Monstrosität", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Streitkolben\n12 - 25 Schaden Geschwindigkeit 3.60\n(5.1 Schaden pro Sekunde)\n+7 Stärke\n+10 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\n+ 8 Vielseitigkeit\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[168479] = { ["name"] = "Truppenmobilisierung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Die Entfesselten\n- Respektvoll\n\"Fügt Trupps, die für Missionen angeworben wurden, entfesselte Söldner hinzu.\"" }
