entries[168481] = { ["name"] = "Uralter Beschleuniger", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verleiht Eurem Herz von Azeroth 'Vision der Perfektion'.\nGroße Macht:\nVision der Perfektion\nEure Zauber und Fähigkeiten haben eine Chance, ' ' für 25% der Grunddauer zu aktivieren .\nGeringe Macht:\nStreben nach Perfektion\nVerringert die Abklingzeit von ' ' um [(( 6849 + 3320) /- 100) ; Min 10, Max 25]% .\n\"Träumt von der Zukunft, konzentriert Euch auf die Gegenwart.\"" }
entries[168482] = { ["name"] = "Benthischer Versiegler", ["text"] = "Questgegenstand\nBenutzen: Verschließt den Geysir mit kraftvoller Dichtungsmasse! (3 Sek. Abklingzeit)" }
entries[168483] = { ["name"] = "Protokollübertragungsgerät", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stiehlt einem mechanischen Ziel alle nützlichen Effekte. Kann nur in Zandalar und Kul Tiras verwendet werden. (1 Min Abklingzeit)" }
entries[168487] = { ["name"] = "Zin'anthide", ["text"] = "Handwerksmaterial\n\"Wird von Spielercharakteren gesammelt, die den Beruf Kräuterkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[168488] = { ["name"] = "Verlorener Münzbeutel des Seefahrers", ["text"] = "Wird beim Aufheben gebunden\n\"Es ist nur noch eine Münze übrig.\"\n<Zum Öffnen rechtsklicken>" }
