entries[168501] = { ["name"] = "Überlegener Stahlhauttrank", ["text"] = "Benutzen: Verleiht Eurem Körper widerstandfähige Energie, die Eure Rüstung 25 Sek. lang um 363 erhöht. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[168502] = { ["name"] = "Trank der Rekonstitution", ["text"] = "Benutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 816 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[168506] = { ["name"] = "Trank der festen Entschlossenheit", ["text"] = "Benutzen: Konzentriert Euren Blick auf einen einzelnen Gegner. Eure Schaden verursachenden Fähigkeiten markieren das Ziel und erhöhen Eure Chance auf kritische Treffer gegen dieses Ziel um bis zu 20%. Wenn Ihr einem neuen Ziel Schaden zufügt, wird Euer Fokus zurückgesetzt. Hält 25 Sek. lang an. Funktioniert nicht bei Zielen über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:" }
