entries[168529] = { ["name"] = "Trank der umzingelten Stärke", ["text"] = "Benutzen: Ermächtigt Eure Fähigkeiten und erhöht Eure Hauptwert 25 Sek. lang um 108 . Euer Primärwert erhöht sich zusätzlich um die Zahl der Gegner innerhalb von 8 Metern von Euch, bis zu einem Maximum von ( 108 * 5). (5 Min Abklingzeit)\nVerkaufspreis:" }
