entries[168533] = { ["name"] = "Bauplan: Üb3r-Modul: P.O.G.O.", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Üb3r-Modul: P.O.G.O. herstellt.\nErschafft ein Üb3r-Modul: P.O.G.O.\nBenötigt Ingenieurskunst von Kul Tiras (150)\nBenötigt Rostbolzenwiderstand\n- Respektvoll\n\nÜb3r-Modul: P.O.G.O.\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Garantiert, dass Eure Üb3r-Erfindungen P.O.G.O.s sind.\nBenötigt Ingenieurskunst von Kul Tiras (50)\nBenötigt Moneliterz (5), Sturmsilbererz (2), Isoliertes Kabel (15), Chemische Sprengkapsel (10)" }
entries[168534] = { ["name"] = "Bauplan: Üb3r-Modul: Üb3r-Spule", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Üb3r-Modul: Üb3r-Spule herstellt.\nErschafft ein Üb3r-Modul: P.O.G.O.\nBenötigt Ingenieurskunst von Kul Tiras (150)\nBenötigt Rostbolzenwiderstand\n- Respektvoll\n\nÜb3r-Modul: Üb3r-Spule\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Garantiert, dass Eure Üb3r-Erfindungen Üb3r-Spulen sind.\nBenötigt Ingenieurskunst von Kul Tiras (50)\nBenötigt Moneliterz (5), Sturmsilbererz (2), Isoliertes Kabel (15), Chemische Sprengkapsel (10)" }
entries[168535] = { ["name"] = "Bauplan: Üb3r-Modul: Schrottkanone", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein Üb3r-Modul: Schrottkanone herstellt.\nErschafft ein Üb3r-Modul: Schrottkanone.\nBenötigt Ingenieurskunst von Kul Tiras (150)\nBenötigt Rostbolzenwiderstand\n- Respektvoll\n\nÜb3r-Modul: Schrottkanone\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Garantiert, dass Eure Üb3r-Erfindungen Schrottkanonen sind.\nBenötigt Ingenieurskunst von Kul Tiras (50)\nBenötigt Moneliterz (5), Sturmsilbererz (2), Isoliertes Kabel (15), Chemische Sprengkapsel (10)" }
entries[168536] = { ["name"] = "Rekristallisierende Azeritformation", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Azeroths unsterbliches Geschenk'.\nGroße Macht:\nAzeroths unsterbliches Geschenk\nSofort 45 sek. Abklingzeit Verringert 4 Sek. lang sämtlichen von Euch erlittenen Schaden um 20%.\nGeringe Macht:\nVerhärtetes Azerit\nWenn Eure Gesundheit unter 35% fällt, erhaltet Ihr für 8 Sek. 799 Rüstung.\n\nDieser Effekt kann nur einmal alle 120 Sek. auftreten. (2.5Min. Abklingzeit)" }
entries[168537] = { ["name"] = "Gehärtete Azeritformation", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Azeroths unsterbliches Geschenk'.\nErlernt Rang 3 der Kondensierten Lebenskraft, der Vitalitätsverbindung oder von Azeroths unsterblichem Geschenk auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\nAzeroths unsterbliches Geschenk\nSofort 45 sek. Abklingzeit Verringert 2 Sek. lang sämtlichen von Euch erlittenen Schaden um 40% sowie danach 2 Sek. lang um 20%.\nGeringe Macht:\nVerhärtetes Azerit\nWenn Eure Gesundheit unter 35% fällt, erhaltet Ihr 4 Sek. lang ( 799 * 200 / 100) Rüstung sowie danach 4 Sek. lang 799 Rüstung.\n\nDieser Effekt kann nur einmal alle 120 Sek. auftreten. (2.5Min. Abklingzeit)" }
entries[168538] = { ["name"] = "Blendende Azeritformation", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger , Paladin , Todesritter , Mönch , Druide , Dämonenjäger\nBenutzen: Verleiht Eurem Herz von Azeroth 'Azeroths unsterbliches Geschenk'.\nGroße Macht:\nAzeroths unsterbliches Geschenk\nSofort 45 sek. Abklingzeit Verringert 2 Sek. lang sämtlichen von Euch erlittenen Schaden um 40% sowie danach 2 Sek. lang um 20%.\nGeringe Macht:\nVerhärtetes Azerit\nWenn Eure Gesundheit unter 35% fällt, erhaltet Ihr 4 Sek. lang ( 799 * 200 / 100) Rüstung sowie danach 4 Sek. lang 799 Rüstung.\n\nDieser Effekt kann nur einmal alle 120 Sek. auftreten. (2.5Min. Abklingzeit)" }
entries[168539] = { ["name"] = "Biolumineszenter Schleim", ["text"] = "Questgegenstand\n\"Geruchlos und leuchtend.\"" }
entries[168540] = { ["name"] = "Tiefseekristall", ["text"] = "Questgegenstand\nEinzigartig\n\"Glänzt wie ein Diamant.\"" }
entries[168541] = { ["name"] = "Azeritdetektor", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Hüllt Eure Umgebung in biolumineszentes Licht, sodass Ihr die Spuren von Azeritrückständen sehen könnt." }
entries[168543] = { ["name"] = "Schlüsselsteinaffix hinzufügen: Schröpfend", ["text"] = "Benutzen: Fügt einem mythischen Schlüsselstein das Affix Schröpfend hinzu.\nVerkaufspreis:" }
entries[168558] = { ["name"] = "Fetisch der tiefen Verliese", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Anima von Leben und Tod'.\nGroße Macht:\nAnima des Todes\nSofort 2 min Abklingzeit Ihr nutzt Eure Lebenskraft, um Gegner zu verbrennen. Ihr fügt allen Gegnern in der Nähe 10% Eurer maximalen Gesundheit als Feuerschaden zu und werdet pro getroffenem Gegner um 5% Eurer maximalen Gesundheit geheilt, bis zu 25% Eurer maximalen Gesundheit.\nGeringe Macht:\nAnima des Lebens\nAzeritenergie strömt durch Eure Adern und erhöht Eure maximale Gesundheit alle 5 Sek. um 244 . Bis zu 10-mal stapelbar.\n\nGewährt Euch einen Stapel von 'Anima des Lebens', wenn Ihr einen Gegner besiegt, der Erfahrung oder Ehre gewährt.\n\nDieser Effekt endet, wenn Eure Gesundheit unter 35% fällt." }
entries[168559] = { ["name"] = "Fetisch der verborgenen Labyrinthe", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Anima von Leben und Tod'.\nErlernt Rang 3 der Essenz der Fokussierungsiris, der Invokation der Lebensbinderin oder der Anima von Leben und Tod auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\nAnima des Todes\nSofort 2 min Abklingzeit Ihr nutzt Eure Lebenskraft, um Gegner zu verbrennen. Ihr fügt allen Gegnern in der Nähe 10% Eurer maximalen Gesundheit als Feuerschaden zu und werdet pro getroffenem Gegner um 10% Eurer maximalen Gesundheit geheilt, bis zu 50% Eurer maximalen Gesundheit.\nGeringe Macht:\nAnima des Lebens\nAzeritenergie strömt durch Eure Adern und erhöht Eure maximale Gesundheit alle 5 Sek. um 244 . Bis zu 10-mal stapelbar. Während Ihr über maximale Stapel verfügt, werdet Ihr alle 5 Sek. um 185 Gesundheit geheilt.\n\nGewährt Euch einen Stapel von 'Anima des Lebens', wenn Ihr einen Gegner besiegt, der Erfahrung oder Ehre gewährt.\n\nDieser Effekt endet, wenn Eure Gesundheit unter 35% fällt." }
